def undirected_edges(backend):
    return sorted({tuple(sorted((int(a), int(b)))) for a, b in backend.coupling_map.get_edges()})


def wait_dt_of(t_us, backend):
    g = getattr(backend.target, "granularity", 1) or 1
    return W.even_wait(t_us * 1e-6 / backend.dt, g), g


def logical_ramsey(quad, wait_dt):
    """Test 7's one-qubit circuit (hw_t10.logical_ramsey): X, the package's Part B Ramsey on one qubit, H, the wait, H,
    measure; Y, the same with an S-dagger inserted right before the final H."""
    qc = W.part_b_circuit(1, wait_dt, "R")
    if quad == "Y":
        from qiskit.circuit import CircuitInstruction
        from qiskit.circuit.library import SdgGate
        k = max(i for i, x in enumerate(qc.data) if x.operation.name == "h")
        qc.data.insert(k, CircuitInstruction(SdgGate(), (qc.qubits[0],)))
        qc.name = f"Y{wait_dt}"
    return qc


def logical_readout(k):
    from qiskit import QuantumCircuit
    qc = QuantumCircuit(1, 1, name=k)
    if k == "P01":
        qc.x(0)
    qc.measure(0, 0)
    return qc


def on_set(one, qs, name):
    from qiskit import QuantumCircuit
    n = len(qs)
    qc = QuantumCircuit(n, n, name=name)
    for k in range(n):
        qc.compose(one, qubits=[k], clbits=[k], inplace=True)
    return qc


def build_set(qs, backend, waits=WAITS_US):
    """Job 1: X and Y at each wait on every qubit of the set and the two readout circuits (hw_t10.build_set)."""
    qs = sorted(int(q) for q in qs)
    circ, info, ref = {}, {}, {}
    for t in waits:
        wdt, g = wait_dt_of(t, backend)
        for quad in QUADS:
            one = logical_ramsey(quad, wdt)
            circ[(quad, t)] = W.to_backend(on_set(one, qs, f"{quad}{wdt}-n{len(qs)}"), qs, backend)
            info[(quad, t)] = {"t_requested_us": t, "requested_dt": t * 1e-6 / backend.dt, "wait_dt": wdt, "granularity": g,
                               "logical_one_qubit": W.structure(one)}
            ref[(quad, t)] = one
    for k in READOUT:
        one = logical_readout(k)
        circ[(k, None)] = W.to_backend(on_set(one, qs, f"{k}-n{len(qs)}"), qs, backend)
        info[(k, None)] = {}
        ref[(k, None)] = one
    return circ, info, ref, qs


def ops_of(c, q=None):
    out = []
    for i in c.data:
        qs = [c.find_bit(x).index for x in i.qubits]
        if q is not None and q not in qs:
            continue
        out.append((i.operation.name, qs, [c.find_bit(x).index for x in i.clbits]))
    return out


def seq_of(c, q):
    out = []
    for i in c.data:
        if q not in [c.find_bit(x).index for x in i.qubits]:
            continue
        op = i.operation
        if op.name == "rz":
            out.append(("rz", round(math.degrees(float(op.params[0])), 6)))
        elif op.name == "delay":
            out.append(("delay", int(op.duration)))
        else:
            out.append((op.name, None))
    return out


def digest(c):
    def par(op):
        try:
            return [round(float(x), 12) for x in op.params]
        except Exception:
            return [str(x) for x in op.params]
    seq = [(i.operation.name, [c.find_bit(x).index for x in i.qubits], [c.find_bit(x).index for x in i.clbits], par(i.operation)) for i in c.data]
    return hashlib.sha256(json.dumps(seq).encode()).hexdigest()


def exact_p1_per_qubit(c, qs):
    """hw_t10.exact_p1_per_qubit: each qubit's own instructions on a one-qubit circuit, manacitra.wait.exact_distribution."""
    from qiskit import QuantumCircuit
    by_q = defaultdict(list)
    for i in c.data:
        qq = [c.find_bit(x).index for x in i.qubits]
        if len(qq) == 1:
            by_q[qq[0]].append(i)
    out = {}
    for q in qs:
        sub = QuantumCircuit(1, 1)
        for i in by_q[q]:
            sub.append(i.operation, [sub.qubits[0]], [sub.clbits[0]] if i.clbits else [])
        p = W.exact_distribution(sub)
        out[str(q)] = sum(v for key, v in p.items() if key[-1] == "1")
    return out


def scheduled_waits(c, qs, backend):
    sch = W.scheduled(c, backend.target)
    ins = K50.instructions(sch)
    out = {}
    for q in qs:
        mine = [x for x in ins if x[1] == [q]]
        tl = K50.timed(mine, backend.target, backend.dt, [q])
        w = K50.window(tl, q)
        delays = [int(op.duration) for op, qq, _ in K50.instructions(c) if op.name == "delay" and qq == [q]]
        out[q] = {"T_dt": int(w["T_dt"]), "T_us": w["T_dt"] * backend.dt * 1e6, "n_sx": w["n_sx"], "delays_dt": delays}
    return out


def edge_record(qs, edges):
    shared = sorted([a, b] for a, b in edges if a in qs and b in qs)
    return {"n_qubits": len(qs), "no_two_qubits_share_an_edge": not shared, "edges_inside_the_set": shared}


def set_checks(circ, info, ref, qs, edges, backend):
    """Job 1's structural checks (hw_t10.set_checks)."""
    rank = {q: k for k, q in enumerate(qs)}
    er = edge_record(qs, edges)
    recs, ok = {"set": er}, er["no_two_qubits_share_an_edge"]
    refseq_cache = {}
    for (k, t), c in circ.items():
        r = {}
        allops = ops_of(c)
        used = {q for _, qq, _ in allops for q in qq}
        r["every_instruction_on_11_or_95"] = used <= set(qs)
        r["every_qubit_of_the_set_used"] = used == set(qs)
        r["no_instruction_on_two_or_more_qubits"] = all(len(qq) == 1 for _, qq, _ in allops)
        meas = [(qq[0], cs[0]) for nm, qq, cs in allops if nm == "measure"]
        r["n_clbits_is_2"] = c.num_clbits == len(qs)
        r["each_qubit_measured_once_into_its_own_clbit"] = (len(meas) == len(qs) and sorted(q for q, _ in meas) == qs
                                                           and all(cb == rank[q] for q, cb in meas))
        if (k, t) not in refseq_cache:
            refseq_cache[(k, t)] = {q: seq_of(W.to_backend(ref[(k, t)], [q], backend), q) for q in qs}
        seqs = {q: seq_of(c, q) for q in qs}
        r["each_qubit_carries_test7s_sequence"] = all(seqs[q] == refseq_cache[(k, t)][q] for q in qs)
        p1 = exact_p1_per_qubit(c, qs)
        r["exact_P1_per_qubit"] = p1
        if k in QUADS:
            i = info[(k, t)]
            names = {q: [nm for nm, _ in seqs[q] if nm != "delay"] for q in qs}
            if k == "X":
                r["X_names_rz_sx_rz_rz_sx_rz_measure"] = all(names[q] == ["rz", "sx", "rz", "rz", "sx", "rz", "measure"] for q in qs)
            else:
                xs = {q: [s for s in seq_of(circ[("X", t)], q) if s[0] != "delay"] for q in qs}
                ys = {q: [s for s in seqs[q] if s[0] != "delay"] for q in qs}
                r["Y_is_X_with_one_rz_minus_90_before_the_last_H"] = all(ys[q] == xs[q][:3] + [("rz", -90.0)] + xs[q][3:] for q in qs)
            sw = scheduled_waits(c, qs, backend)
            i["scheduled"] = {str(q): v for q, v in sw.items()}
            r["delay_is_wait_dt_on_every_qubit"] = all(sw[q]["delays_dt"] == ([i["wait_dt"]] if i["wait_dt"] else []) for q in qs)
            r["scheduled_is_wait_dt_on_every_qubit"] = all(sw[q]["T_dt"] == i["wait_dt"] for q in qs)
            r["two_sx_on_every_qubit"] = all(sw[q]["n_sx"] == 2 for q in qs)
            r["wait_even"] = i["wait_dt"] % 2 == 0
            want = 0.0 if k == "X" else 0.5
        else:
            r["gates"] = sorted({nm for nm, _ in seqs[qs[0]] if nm not in ("delay", "barrier")})
            want = 0.0 if k == "P10" else 1.0
        r["exact_P1_expected"] = want
        r["exact_P1_as_expected_on_every_qubit"] = all(abs(v - want) < 1e-9 for v in p1.values())
        good = all(v for v in r.values() if isinstance(v, bool))
        r["pass"] = good
        ok = ok and good
        recs[f"{k}|{t}"] = r
    waits = [{"t_requested_us": t, "requested_dt": info[("X", t)]["requested_dt"], "wait_dt": info[("X", t)]["wait_dt"],
              "scheduled_dt": {q: sorted({v["T_dt"] for v in info[(q, t)]["scheduled"].values()}) for q in QUADS},
              "scheduled_us": {q: sorted({v["T_us"] for v in info[(q, t)]["scheduled"].values()}) for q in QUADS}} for t in WAITS_US]
    for w in waits:
        w["difference_us"] = {q: [x - w["t_requested_us"] for x in w["scheduled_us"][q]] for q in QUADS}
        w["same_on_every_qubit"] = all(len(w["scheduled_dt"][q]) == 1 for q in QUADS)
    return recs, waits, ok


def build_monitor(qs, backend):
    """The monitor's four distinct circuits on the set (hw_t10.build_monitor): X and Y with each qubit at its own wait,
    and P10 and P01."""
    from qiskit import QuantumCircuit
    qs = sorted(int(q) for q in qs)
    n = len(qs)
    wdt = {q: wait_dt_of(WAITS_US_OF[q], backend)[0] for q in qs}
    circ, info, ref = {}, {}, {}
    for quad in QUADS:
        qc = QuantumCircuit(n, n, name=f"{quad}-monitor-n{n}")
        ones = {}
        for k, q in enumerate(qs):
            one = logical_ramsey(quad, wdt[q])
            qc.compose(one, qubits=[k], clbits=[k], inplace=True)
            ones[q] = one
        circ[quad] = W.to_backend(qc, qs, backend)
        info[quad] = {"wait_us_requested": {str(q): WAITS_US_OF[q] for q in qs}, "wait_dt": {str(q): wdt[q] for q in qs}}
        ref[quad] = ones
    for k in READOUT:
        one = logical_readout(k)
        circ[k] = W.to_backend(on_set(one, qs, f"{k}-n{n}"), qs, backend)
        info[k] = {}
        ref[k] = {q: one for q in qs}
    return circ, info, ref, qs


def qubit_duration_dt(c, q, target, dt):
    return sum(K50.duration(op, qq, target, dt) for op, qq, _ in K50.instructions(c) if qq == [q])


def monitor_checks(circ, info, ref, qs, edges, backend):
    """The monitor's structural checks (hw_t10.monitor_checks)."""
    t, dt = backend.target, backend.dt
    rank = {q: k for k, q in enumerate(qs)}
    er = edge_record(qs, edges)
    recs, ok = {"set": er}, er["no_two_qubits_share_an_edge"]
    waits = {}
    for k, c in circ.items():
        r = {}
        allops = ops_of(c)
        used = {q for _, qq, _ in allops for q in qq}
        r["every_instruction_on_11_or_95"] = used <= set(qs)
        r["every_qubit_of_the_set_used"] = used == set(qs)
        r["no_instruction_on_two_or_more_qubits"] = all(len(qq) == 1 for _, qq, _ in allops)
        meas = [(qq[0], cs[0]) for nm, qq, cs in allops if nm == "measure"]
        r["n_clbits_is_2"] = c.num_clbits == len(qs)
        r["each_qubit_measured_once_into_its_own_clbit"] = (len(meas) == len(qs) and sorted(q for q, _ in meas) == qs and all(cb == rank[q] for q, cb in meas))
        seqs = {q: seq_of(c, q) for q in qs}
        r["each_qubit_carries_test7s_sequence_at_its_own_wait"] = all(seqs[q] == seq_of(W.to_backend(ref[k][q], [q], backend), q) for q in qs)
        p1 = exact_p1_per_qubit(c, qs)
        r["exact_P1_per_qubit"] = p1
        if k in QUADS:
            sw = scheduled_waits(c, qs, backend)
            wd = info[k]["wait_dt"]
            r["delay_is_its_own_wait_on_every_qubit"] = all(sw[q]["delays_dt"] == ([wd[str(q)]] if wd[str(q)] else []) for q in qs)
            r["scheduled_wait_equals_requested_on_every_qubit"] = all(sw[q]["T_dt"] == wd[str(q)] for q in qs)
            r["two_sx_on_every_qubit"] = all(sw[q]["n_sx"] == 2 for q in qs)
            r["every_wait_even"] = all(wd[str(q)] % 2 == 0 for q in qs)
            qd = {q: qubit_duration_dt(c, q, t, dt) for q in qs}
            longest = max(qs, key=lambda q: (wd[str(q)], q))
            est = int(round(c.estimate_duration(t, unit="dt")))
            r["circuit_duration_dt"] = est
            r["longest_wait_qubit"] = longest
            r["circuit_duration_is_the_longest_wait_qubits_sequence"] = est == qd[longest] == max(qd.values())
            waits[k] = {str(q): {"requested_us": WAITS_US_OF[q], "wait_dt": wd[str(q)], "scheduled_dt": sw[q]["T_dt"], "scheduled_us": sw[q]["T_us"],
                                 "difference_us": sw[q]["T_us"] - WAITS_US_OF[q]} for q in qs}
            want = 0.0 if k == "X" else 0.5
        else:
            want = 0.0 if k == "P10" else 1.0
        r["exact_P1_expected"] = want
        r["exact_P1_as_expected_on_every_qubit"] = all(abs(v - want) < 1e-9 for v in p1.values())
        good = all(v for v in r.values() if isinstance(v, bool))
        r["pass"] = good
        ok = ok and good
        recs[k] = r
    return recs, waits, ok


# --------------------------------------------------------------------------- the order of each job
def order_j1():
    """Every circuit and copy in one random order: numpy.random.default_rng(21302).permutation (hw_t7.assemble)."""
    keys = [("X", t) for t in WAITS_US] + [("Y", t) for t in WAITS_US] + [(k, None) for k in READOUT]
    items = [(key, cp) for key in keys for cp in range(1, COPIES + 1)]
    perm = np.random.default_rng(ORDER_SEED_J1).permutation(len(items))
    return [items[i] for i in perm]


def order_mon(job):
    out = [(k, None, "start") for k in READOUT]
    for r in range(1, N_REP[job] + 1):
        out += [("X", r, "monitor"), ("Y", r, "monitor")]
    return out + [(k, None, "end") for k in READOUT]


CLBITS = "qubit 11 into clbit 0, qubit 95 into clbit 1 (the set in ascending index)"


def assemble(job, circ, info, dt):
    circs, labels, shots = [], [], []
    if job == 1:
        for pos, ((k, t), cp) in enumerate(order_j1()):
            circs.append(circ[(k, t)])
            if k in QUADS:
                i = info[(k, t)]
                T = sorted({v["T_dt"] for v in i["scheduled"].values()})
                lab = {"job": 1, "position": pos, "circuit": k, "quadrature": k, "t_requested_us": t, "wait_dt": i["wait_dt"],
                       "scheduled_wait_dt": T[0], "scheduled_wait_us": T[0] * dt * 1e6, "copy": cp, "qubits": list(QS), "clbits": CLBITS,
                       "built_by": "package: part_b_circuit(1, wait_dt, 'R') on both qubits" + (", with an SdgGate inserted before the final H" if k == "Y" else "") + ", to_backend on [11, 95]"}
            else:
                lab = {"job": 1, "position": pos, "circuit": k, "quadrature": None, "t_requested_us": None, "copy": cp, "qubits": list(QS), "clbits": CLBITS,
                       "built_by": "test 7's one-qubit readout circuit on both qubits, to_backend on [11, 95]"}
            labels.append(lab)
            shots.append(SHOTS_J1)
    else:
        for pos, (k, r, block) in enumerate(order_mon(job)):
            circs.append(circ[k])
            labels.append({"job": job, "position": pos, "block": block, "repeat": r, "circuit": k, "quadrature": k if k in QUADS else None,
                           "qubits": list(QS), "clbits": CLBITS, "waits_us": {str(q): WAITS_US_OF[q] for q in QS} if k in QUADS else None})
            shots.append(SHOTS_MON[job])
    return circs, labels, shots


def order_checks(job, circ, circs, labels, shots):
    """The positions in the rule's order, rebuilt independently of assemble()."""
    pos_dig = [digest(c) for c in circs]
    if job == 1:
        dig = {key: digest(c) for key, c in circ.items()}
        keys = [("X", t) for t in WAITS_US] + [("Y", t) for t in WAITS_US] + [(k, None) for k in READOUT]
        items = [(key, cp) for key in keys for cp in (1, 2)]
        want = [items[i] for i in np.random.default_rng(21302).permutation(260)]
        r = {"n_positions": len(circs), "n_positions_is_260": len(circs) == N_POSITIONS_J1,
             "labels_in_the_seed_21302_order": [((l["circuit"], l["t_requested_us"]), l["copy"]) for l in labels] == want,
             "each_position_carries_its_labels_circuit": pos_dig == [dig[key] for key, cp in want],
             "each_circuit_twice": all(sum(1 for key, cp in want if key == k) == 2 for k in keys),
             "one_shot_count": set(shots) == {SHOTS_J1}, "shots_total": sum(shots), "shots_total_is_390000": sum(shots) == 390_000,
             "interleaving_seed": ORDER_SEED_J1}
    else:
        dig = {k: digest(c) for k, c in circ.items()}
        want = order_mon(job)
        n = N_REP[job]
        r = {"n_positions": len(circs), f"n_positions_is_{N_POSITIONS_MON[job]}": len(circs) == N_POSITIONS_MON[job],
             "labels_in_the_rules_order": [(l["circuit"], l["repeat"], l["block"]) for l in labels] == [tuple(x) for x in want],
             "each_position_carries_its_labels_circuit": pos_dig == [dig[k] for k, rr, b in want],
             "every_repeat_X_then_Y": all(labels[2 + 2 * (k - 1)]["circuit"] == "X" and labels[3 + 2 * (k - 1)]["circuit"] == "Y" for k in range(1, n + 1)),
             "readout_first_and_last": [l["circuit"] for l in labels[:2]] == list(READOUT) and [l["circuit"] for l in labels[-2:]] == list(READOUT),
             "positions_numbered_in_order": [l["position"] for l in labels] == list(range(len(labels))),
             "one_shot_count": set(shots) == {SHOTS_MON[job]}, "shots_total": sum(shots),
             "shots_total_as_the_rule": sum(shots) == {2: 64_000, 3: 64_800}[job],
             "note": "not interleaved; the sampler is given the list as (circuit, None, shots) in this order"}
    r["pass"] = all(v for v in r.values() if isinstance(v, bool))
    return r


def digests(circ):
    return {f"{k[0]}|{k[1]}" if isinstance(k, tuple) else str(k): digest(c) for k, c in circ.items()}


def limits(b, circs, shots):
    cfg = b.configuration()
    used = set().union(*[set(c.count_ops()) for c in circs])
    return {"max_shots": cfg.max_shots, "max_experiments": cfg.max_experiments, "n_positions": len(circs),
            "within": max(shots) <= cfg.max_shots and len(circs) <= cfg.max_experiments,
            "instructions_not_in_target": sorted(used - set(b.target.operation_names) - {"barrier", "delay"})}


def built(b, job):
    edges = undirected_edges(b)
    if job == 1:
        circ, info, ref, qs = build_set(QS, b)
        recs, waits, ok = set_checks(circ, info, ref, qs, edges, b)
    else:
        circ, info, ref, qs = build_monitor(QS, b)
        recs, waits, ok = monitor_checks(circ, info, ref, qs, edges, b)
    circs, labels, shots = assemble(job, circ, info, b.dt)
    order = order_checks(job, circ, circs, labels, shots)
    lim = limits(b, circs, shots)
    ok = ok and order["pass"] and lim["within"] and not lim["instructions_not_in_target"]
    return circ, info, recs, circs, labels, shots, lim, waits, order, ok


def estimate(job, n_shots):
    s = RATE[job]["s_per_shot"] * n_shots
    return {"shots": n_shots, "rate_s_per_shot": RATE[job]["s_per_shot"], "rate_from": RATE[job]["from"], "expected_s": s,
            "with_margin_s": 1.5 * s, "beside_ibm_formula_s": 2 + 0.35e-3 * n_shots, "beside_ibm_formula_note": "2 s per job + 0.35 ms per shot"}


def shots_of(job):
    return N_POSITIONS_J1 * SHOTS_J1 if job == 1 else N_POSITIONS_MON[job] * SHOTS_MON[job]


def sampler_for(b, job):
    smp = K50.make_sampler(b)
    smp.options.environment.job_tags = [TAGS[job]]
    so = smp.options
    sopt = {"dynamical_decoupling_enable": so.dynamical_decoupling.enable, "twirling_enable_gates": so.twirling.enable_gates,
            "twirling_enable_measure": so.twirling.enable_measure, "job_tags": list(so.environment.job_tags)}
    good = (sopt["dynamical_decoupling_enable"] is False and sopt["twirling_enable_gates"] is False
            and sopt["twirling_enable_measure"] is False and sopt["job_tags"] == [TAGS[job]])
    return smp, sopt, good


def summary(recs):
    bad = [k for k, r in recs.items() if isinstance(r, dict) and "pass" in r and not r["pass"]]
    return {"circuits": sum(1 for r in recs.values() if isinstance(r, dict) and "pass" in r), "failing": bad,
            "set": recs.get("set")}


# --------------------------------------------------------------------------- the inputs


def meta():
    import qiskit
    import qiskit_ibm_runtime
    return {"script_sha256": sha(__file__), "qiskit": qiskit.__version__, "qiskit_ibm_runtime": qiskit_ibm_runtime.__version__,
            "numpy": np.__version__, "manacitra_commit": COMMIT, "manacitra_version_string": manacitra.__version__,
            "manacitra_wait_sha256": sha(HERE / "site/manacitra/wait.py"), "utc": now()}


# --------------------------------------------------------------------------- the decision, before each build
def final_status_of(job):
    if recorded(f"results-t21-job{job}-counts.json"):
        return "DONE"
    d = recorded(f"decision-t21-job{job}.json")
    if d and not d["decision"]["runs"]:
        return "NOT RUN"
    f = recorded(f"failed-t21-job{job}.json")
    return f["status"] if f else None


def write_decision(job):
    """decision-t21-job{job}.json, recorded before the job is built (t21-rule.md section 2, "The allowance, and which job
    gives way"). Jobs 2 and 3 are decided only after the previous job reached a final status."""
    p = HERE / f"decision-t21-job{job}.json"
    if p.exists():
        sys.exit("refusing: the decision is recorded")
    if job > 1 and final_status_of(job - 1) is None:
        sys.exit(f"STOP: job {job - 1} has not reached a recorded final status; job {job} is not decided")
    svc = service()
    u = usage(svc)
    est = estimate(job, shots_of(job))
    rem = None if u["remaining_s"] is None else float(u["remaining_s"])
    within = rem is not None and est["with_margin_s"] <= rem
    margins = {j: estimate(j, shots_of(j))["with_margin_s"] for j in (1, 2, 3)}
    if job == 1:
        if rem is not None and rem >= margins[1] + margins[2] + margins[3]:
            plan, runs, why = "ALL THREE", True, "the allowance covers all three estimates with their margins: all three run in order"
        elif rem is not None and rem >= margins[2] + margins[3]:
            plan, runs, why = "MONITORS ONLY", False, "the allowance covers the two monitors with their margins but not the scan as well: the scan is not run, and question 1 reports no word"
        elif rem is not None and rem >= margins[2]:
            plan, runs, why = "JOB 2 ALONE", False, "the allowance covers less than both monitors, and job 2's own estimate with its margin is covered: job 2 runs alone"
        else:
            plan, runs, why = "NOTHING", False, "the allowance does not cover job 2's estimate with its margin: nothing is submitted"
    else:
        plan = recorded("decision-t21-job1.json")["decision"]["plan"]
        if plan == "NOTHING" or (job == 3 and plan == "JOB 2 ALONE"):
            runs, why = False, f"the plan recorded before job 1 is {plan}: job {job} does not run"
        else:
            runs = within
            why = ("after the first job, the job's estimate with the margin is within the allowance read before it" if runs
                   else "the job's estimate with the margin exceeds the allowance read before it: the job does not run")
            if plan in ("MONITORS ONLY", "JOB 2 ALONE") and job == 2:
                why = ("job 2 is the first job; its estimate with the margin is within the allowance read before it" if runs
                       else "job 2's estimate with the margin exceeds the allowance read before it: nothing is submitted")
    rec = {"job": job, "computed_utc": now(), "usage_read": u, "estimate": est, "margins_all_jobs_s": margins,
           "previous_job_final_status": final_status_of(job - 1) if job > 1 else None,
           "decision": {"runs": runs, "plan": plan, "within_allowance_this_job": within,
                        "rule": "t21-rule.md section 2, 'The allowance, and which job gives way'", "reason": why}}
    p.write_text(json.dumps(rec, indent=1))
    log(f"decision for job {job} recorded before its build: remaining {u['remaining_s']} s at {u['read_utc']}; estimate {est['expected_s']:.1f} s, "
        f"with the margin {est['with_margin_s']:.1f} s (IBM's formula {est['beside_ibm_formula_s']:.1f} s); plan {plan}; runs {runs}")
    return rec


