# --------------------------------------------------------------------------- the fetch (hw_t20)
def spans_record(res):
    md = res.metadata or {}
    spans = list((md.get("execution") or {}).get("execution_spans") or [])
    rows = []
    def runs(mask):
        """The shot indices a span holds of one position, as [start, stop) runs over the flattened mask."""
        m = np.asarray(mask, bool).reshape(-1).astype(np.int8)
        d = np.diff(np.concatenate([[0], m, [0]]))
        return {"n_shots_in_mask": int(m.size), "runs": [[int(a), int(b)] for a, b in zip(np.flatnonzero(d == 1), np.flatnonzero(d == -1))]}

    for si, s in enumerate(spans):
        pubs = sorted(int(p) for p in s.pub_idxs)
        rows.append({"span": si, "start_utc": s.start.isoformat(), "stop_utc": s.stop.isoformat(), "duration_s": s.duration, "size_shots": int(s.size),
                     "positions": pubs, "shots_per_position": {str(p): int(np.asarray(s.mask(p)).sum()) for p in pubs},
                     "shot_index_runs": {str(p): runs(s.mask(p)) for p in pubs}, "type": type(s).__name__})

    def js(v):
        if isinstance(v, dict):
            return {str(k): js(x) for k, x in v.items()}
        if isinstance(v, (list, tuple)):
            return [js(x) for x in v]
        if isinstance(v, (int, float, bool, str)) or v is None:
            return v
        return str(v)
    return {"present": bool(spans), "metadata_keys": sorted(md.keys()), "execution_keys": sorted((md.get("execution") or {}).keys()),
            "metadata_other": js({k: v for k, v in md.items() if k != "execution"}), "execution_spans": rows,
            "pub_metadata": [js(res[i].metadata) for i in range(len(res))]}


def fetch(job, job_id, M_):
    svc = service()
    j = svc.job(job_id)
    st = str(j.status())
    log(f"job {job} {job_id} status {st}")
    sub = json.loads((HERE / f"submit-t21-job{job}.json").read_text())
    assert sub["job_id"] == job_id
    if any(f in st for f in ("ERROR", "CANCELLED")):
        try:
            msg = str(j.error_message())
        except Exception as e:
            msg = type(e).__name__
        rec = {"job": job, "job_id": job_id, "status": "ERROR" if "ERROR" in st else "CANCELLED", "status_raw": st, "recorded_utc": now(),
               "error_message": msg, "note": "recorded and never resubmitted (t21-rule.md section 2)"}
        (HERE / f"failed-t21-job{job}.json").write_text(json.dumps(rec, indent=1))
        record_stamp(svc.backend(BACKEND), f"job {job} after final status", st)
        sys.exit(f"job {job} ended {st}; recorded in failed-t21-job{job}.json; never resubmitted")
    if "DONE" not in st:
        sys.exit("not done; nothing written")
    res = j.result()
    counts = [res[k].data.c.get_counts() for k in range(len(sub["labels"]))]
    try:
        ex = spans_record(res)
    except Exception as e:
        ex = {"present": False, "error": type(e).__name__}
    mt = j.metrics()
    use = mt.get("usage") or {}
    for x in use.get("details", []):
        (x.get("metric") or {}).pop("id", None)
    try:
        opts = j.inputs.get("options")
    except Exception:
        opts = None
    after = record_stamp(svc.backend(BACKEND), f"job {job} after fetch", st)
    out = {"meta": M_, "job": job, "job_id": job_id, "backend": BACKEND, "qubits": list(QS), "clbits": CLBITS, "dt_s": sub["dt_s"], "waits": sub["waits"],
           "timestamps": mt.get("timestamps"), "usage": use, "job_options_as_recorded_by_ibm": opts,
           "calibration_at_submission": sub["calibration_at_submission"], "calibration_after_fetch": after["stamp_raw"],
           "fetched_utc": after["utc"], "labels": sub["labels"], "shots": sub["shots"], "counts": counts,
           "result_length_equals_positions": len(res) == len(sub["labels"]), "execution_metadata": ex}
    (HERE / f"results-t21-job{job}-counts.json").write_text(json.dumps(out, default=str))
    log(f"job {job} fetched {len(counts)} positions; execution metadata saved {ex.get('present')} ({len(ex.get('execution_spans', []))} spans); "
        f"recorded machine time {use.get('qpu_charge_time_seconds')} s; calibration after {after['stamp_raw']}; options by IBM {opts}")


# --------------------------------------------------------------------------- the dry run
def dryrun(M_):
    """Every job's build and every check on FakeKingston, offline: nothing submitted."""
    from qiskit_ibm_runtime.fake_provider import FakeKingston
    b = FakeKingston()
    out, ok_all = {}, True
    for job in (1, 2, 3):
        circ, info, recs, circs, labels, shots, lim, waits, order, ok = built(b, job)
        smp, sopt, sgood = sampler_for(b, job)
        out[str(job)] = {"summary": summary(recs), "checks": recs, "order_checks": order, "limits": lim, "sampler_options": sopt, "waits": waits,
                         "n_positions": len(circs), "shots": sum(shots), "first_labels": labels[:6], "digests": digests(circ),
                         "estimate": estimate(job, sum(shots)), "all_pass": ok and sgood}
        ok_all = ok_all and ok and sgood
        log(f"dry run on {b.name}, job {job}: {summary(recs)}; order {order['pass']}; {len(circs)} positions, {sum(shots)} shots; limits {lim}; "
            f"sampler {sopt}; all {ok and sgood}")
    same = out["2"]["digests"] == out["3"]["digests"]
    rec = {"meta": M_, "backend": b.name, "dt_s": b.dt, "granularity": getattr(b.target, "granularity", 1) or 1, "runs": out,
           "jobs_2_and_3_same_distinct_circuits": same, "all_pass": ok_all and same}
    (HERE / "dryrun-t21.json").write_text(json.dumps(rec, indent=1, default=str))
    if not rec["all_pass"]:
        sys.exit("dry run: a check failed")


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--dryrun", action="store_true")
    ap.add_argument("--go", action="store_true")
    ap.add_argument("--inputs", metavar="RULE_SHA256")
    for j in (1, 2, 3):
        for f in ("decision", "check", "submit"):
            ap.add_argument(f"--{f}{j}", action="store_true")
        ap.add_argument(f"--fetch{j}")
    a = ap.parse_args()
    M_ = meta()
    if a.inputs:
        inp = inputs_static(a.inputs)
        old = recorded("inputs.json") or {}
        if "jobs" in old:
            inp["jobs"] = old["jobs"]
        (HERE / "inputs.json").write_text(json.dumps(inp, indent=1))
        m = inp["manacitra"]
        log(f"inputs: manacitra {m['tag']} at {COMMIT} (tag resolves to {m['tag_resolves_to']}), installed equal to the archive {m['installed_equals_archive']}; "
            f"fit and read code v0.10.0 at {inp['fit_and_read_code']['tag_resolves_to']} (wait.py equal to git {inp['fit_and_read_code']['wait_py_equals_git']}); "
            f"rule sha256 matches {inp['rule']['matches']} ({inp['rule']['size_bytes']} bytes); reused code unchanged {inp['reused_unchanged']}")
        if not (inp["rule"]["matches"] and all(inp["reused_unchanged"].values()) and m["commit_present"] == "commit"
                and m["tag_resolves_to"] == COMMIT and m["installed_equals_archive"] and inp["fit_and_read_code"]["wait_py_equals_git"]
                and inp["fit_and_read_code"]["tag_resolves_to"] == READ_COMMIT):
            sys.exit("STOP: the rule, the package, the commit or the reused code differs from what the runner prompt names")
    if not a.inputs and not (recorded("inputs.json") or {}).get("rule", {}).get("matches"):
        sys.exit("STOP: the rule's hash has not been confirmed")
    if a.dryrun:
        dryrun(M_)
    for j in (1, 2, 3):
        if getattr(a, f"decision{j}"):
            write_decision(j)
        if getattr(a, f"check{j}"):
            live(a, M_, j, True)
        if getattr(a, f"submit{j}"):
