           "duties": [0.20, 0.24], "tau_c": "under three sweeps of 31 ms", "dwells_s_by_threshold_crossings": [0.05, 0.19]}


def sha(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()


def hashes_recorded(path):
    out = {}
    if not Path(path).exists():
        return out
    for line in Path(path).read_text().splitlines():
        parts = line.split()
        if len(parts) == 2 and len(parts[0]) == 64:
            out[parts[1]] = parts[0]
    return out


def readout(labels, counts, shots, clbit):
    p10 = [(sum(m for k, m in counts[i].items() if k.replace(" ", "")[::-1][clbit] == "1"), shots[i]) for i, l in enumerate(labels) if l["circuit"] == "P10"]
    p01 = [(sum(m for k, m in counts[i].items() if k.replace(" ", "")[::-1][clbit] == "1"), shots[i]) for i, l in enumerate(labels) if l["circuit"] == "P01"]
    P10 = sum(a for a, _ in p10) / sum(n for _, n in p10)
    P01 = 1 - sum(a for a, _ in p01) / sum(n for _, n in p01)
    return {"P1_given_0": P10, "P0_given_1": P01, "e": (P10 + P01) / 2, "n_readout_circuits": len(p10) + len(p01),
            "per_circuit": {"P10": [a / n for a, n in p10], "P01_ones": [a / n for a, n in p01]}}


def layout_of(span, shots, n_positions):
    pos = span["positions"]
    n_in = {int(p): int(span["shots_per_position"][str(p)]) for p in pos}
    if all(n_in[p] == shots[p] for p in pos):
        return {"kind": "WHOLE POSITIONS", "positions": pos}
    runs = span.get("shot_index_runs")
    if (sorted(pos) == list(range(n_positions)) and len(set(n_in.values())) == 1 and runs
            and len({json.dumps(runs[str(p)]["runs"]) for p in pos}) == 1):
        idx = np.concatenate([np.arange(a, b) for a, b in runs[str(pos[0])]["runs"]])
        return {"kind": "A SLICE OF EVERY POSITION", "positions": pos, "shot_indices_runs": runs[str(pos[0])]["runs"], "idx": idx}
    return {"kind": "OTHER", "positions": pos, "shots_in_span": n_in}


def read_job(job, rec, arrays, fits1, published):
    labels, counts, shots = rec["labels"], rec["counts"], rec["shots"]
    spans = rec["execution_metadata"]["execution_spans"]
    n = len(labels)
    out = {"job": job, "job_id": rec["job_id"], "n_positions": n, "shots_per_position": sorted(set(shots)),
           "spans": [{k: v for k, v in s.items() if k not in ("shot_index_runs", "shots_per_position")} | {"shots_per_position_set": sorted(set(s["shots_per_position"].values()))}
                     for s in spans]}
    # the counts check, position for position, joint key and per qubit
    mism = []
    for i in range(n):
        a = arrays[f"p{i:03d}"]
        if a.shape != (shots[i], 2):
            mism.append({"position": i, "shape": list(a.shape)})
            continue
        keys = [f"{int(r[1])}{int(r[0])}" for r in a]
        joint = {}
        for k in keys:
            joint[k] = joint.get(k, 0) + 1
        pub = {k.replace(" ", ""): v for k, v in counts[i].items() if v}
        if joint != pub:
            mism.append({"position": i, "joint": joint, "published": pub})
        for q in QS:
            ones_a = int(a[:, CLBIT[q]].sum())
            ones_p = sum(m for k, m in counts[i].items() if k.replace(" ", "")[::-1][CLBIT[q]] == "1")
            if ones_a != ones_p:
                mism.append({"position": i, "qubit": q, "ones_array": ones_a, "ones_published": ones_p})
    out["counts_check"] = {"positions": n, "mismatches": mism, "pass": not mism}
    if mism:
        out["note"] = "the counts recomputed from the arrays differ from the published counts: the read of this job stops (test 15 section 3)"
        return out
    lay = [layout_of(s, shots, n) for s in spans]
    out["layout"] = [{k: v for k, v in L.items() if k != "idx"} for L in lay]
    out["layout_readable"] = all(L["kind"] != "OTHER" for L in lay)
    rep = {}
    for i, l in enumerate(labels):
        if l["circuit"] in ("X", "Y") and l.get("repeat") is not None:
            rep.setdefault(int(l["repeat"]), {})[l["circuit"]] = i
    reps = sorted(rep)
    out["repeats"] = len(reps)
    out["qubits"] = {}
    for q in QS:
        cb = CLBIT[q]
        ro = readout(labels, counts, shots, cb)
        ro["published_readout_error_at_the_stamp_in_force"] = published.get(q)
        usable = ro["e"] <= E_MAX
        Q = {"qubit": q, "clbit": cb, "readout": ro, "usable": usable}
        MX_job = np.stack([arrays[f"p{rep[k]['X']:03d}"][:, cb] for k in reps]).astype(float)
        MY_job = np.stack([arrays[f"p{rep[k]['Y']:03d}"][:, cb] for k in reps]).astype(float)
        qr = RC.quadrature_of_record(MX_job, MY_job)
        Q["quadrature_of_record"] = qr
        quad = qr["quadrature"]
        if not out["layout_readable"]:
            Q["note"] = "a span's layout is not one the rule describes: recorded, and the job's read reports no word"
            out["qubits"][str(q)] = Q
            continue
        rows_span = []
        for s, L in zip(spans, lay):
            S = {"span": s["span"], "layout": L["kind"], "duration_s": s["duration_s"], "start_utc": s["start_utc"], "stop_utc": s["stop_utc"]}
            if L["kind"] == "WHOLE POSITIONS":
                inside = set(L["positions"])
                whole = [k for k in reps if rep[k]["X"] in inside and rep[k]["Y"] in inside]
                straddle = [k for k in reps if (rep[k]["X"] in inside) != (rep[k]["Y"] in inside)]
                S.update({"whole_repeats": whole, "straddling_repeats": straddle})
                if len(whole) < 2:
                    S["note"] = "fewer than two whole repeats: not read"
                    rows_span.append(S)
                    continue
                MX = np.stack([arrays[f"p{rep[k]['X']:03d}"][:, cb] for k in whole]).astype(float)
                MY = np.stack([arrays[f"p{rep[k]['Y']:03d}"][:, cb] for k in whole]).astype(float)
                n_shots = MX.shape[1]
                S["shots_per_position"] = n_shots
            else:
                idx = L["idx"]
                MX = np.stack([arrays[f"p{rep[k]['X']:03d}"][idx, cb] for k in reps]).astype(float)
                MY = np.stack([arrays[f"p{rep[k]['Y']:03d}"][idx, cb] for k in reps]).astype(float)
                n_shots = len(idx)
                S.update({"rows": reps, "shot_indices_runs": L["shot_indices_runs"], "shots_per_position": n_shots})
            sweep_s = s["duration_s"] / n_shots
            M = MX if quad == "X" else MY
            r = RC.read_span(M, sweep_s, s["duration_s"])
            S["read"] = r
            S["sweep_s"] = sweep_s
            S["sweep_clock_note"] = "the returned order; in seconds only if it is chronological and even"
            S["beside_emissions"] = RC.emissions(MX, MY, M.mean(axis=0), r["two_state"]["threshold"])
            S["beside_other_quadrature_sharing_ratio"] = RC.sharing_word(MY if quad == "X" else MX)["ratio"]
            if usable:
                S["words"] = {"sharing": r["sharing"]["word"], "timing": r.get("timing_word"), "duty": r.get("duty_word")}
            else:
                S["words"] = None
                S["no_word_reason"] = f"qubit {q} not usable in job {job} (section 3): readout error {ro['e']:.4f} above 0.03"
            rows_span.append(S)
        Q["spans"] = rows_span
        bnd = []
        for a, b in zip(rows_span, rows_span[1:]):
            if usable and "read" in a and "read" in b:
                w = RC.boundary_word(a["read"], b["read"])
                bnd.append({"spans": [a["span"], b["span"]], "boundary": w,
                            "note": None if w else "no boundary word: a duty is not read on one side"})
        Q["boundaries"] = bnd
        f1 = (fits1 or {}).get("qubits", {}).get(str(q), {}).get("t21", {})
        Q["beside_job1_lines_at_monitor_wait"] = f1.get("lines_at_monitor_wait") if f1.get("verdict") == "TWO FIXED FREQUENCIES" else None
        out["qubits"][str(q)] = Q
    return out




if __name__ == "__main__":
    main()

