import hashlib
import json
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent


def sha(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()


def main(key):
    src = HERE / f"results-t21-{key}-counts.json"
    dst = OUT / f"counts-t21-{key}.json"
    if dst.exists():
        sys.exit("refusing: the copy is written")
    r = json.loads(src.read_text())
    r.pop("usage", None)
    dst.write_bytes(json.dumps(r, default=str).encode())
    cp_p = OUT / "copies-t21.json"
    cp = json.loads(cp_p.read_text()) if cp_p.exists() else {}
    cp[key] = {"as_fetched": src.name, "as_fetched_sha256": sha(src), "copied_as": dst.name, "copied_sha256": sha(dst), "removed": ["usage"]}
    cp_p.write_text(json.dumps(cp, indent=1))
    print(f"{key}: {dst.name} written, usage removed")


if __name__ == "__main__":
    if len(sys.argv) > 2:
        OUT = Path(sys.argv[2]).resolve()
    main(sys.argv[1])

